import 'package:flutter/material.dart'; import '../../../../core/theme/app_colors.dart'; import '../../data/repositories/mock_explore_repository.dart';
class ExploreIraqPage extends StatelessWidget { const ExploreIraqPage({super.key}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('اكتشف العراق')),body:StreamBuilder(stream:MockExploreRepository().observeDestinations(),builder:(context,snapshot){if(!snapshot.hasData)return const Center(child:CircularProgressIndicator()); final items=snapshot.data!; return GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:220,mainAxisSpacing:12,crossAxisSpacing:12,childAspectRatio:.8),itemCount:items.length,itemBuilder:(_,i)=>Card(clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Image.network(items[i].coverImageUrl,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const ColoredBox(color:AppColors.primary))),Padding(padding:const EdgeInsets.all(10),child:Text(items[i].nameAr,maxLines:1,overflow:TextOverflow.ellipsis)),Padding(padding:const EdgeInsets.symmetric(horizontal:10),child:Text(items[i].cityAr,style:const TextStyle(color:AppColors.muted))) ]));});});}
